\begin{tikzpicture}[scale=0.62,every node/.style={font=\small},
  nbline/.style={NebulaNavy,thick},
  nbvec/.style={NebulaError,thick,-{Stealth[length=2mm]}},
  nbdash/.style={NebulaCheck,thick,dashed}]
\node[font=\footnotesize\bfseries] at (2.55,3.55) {Flexible piston};
\node[font=\footnotesize\bfseries] at (9.85,3.55) {Rigid sealed vessel};

%% --- Flexible piston, BEFORE heating
\draw[nbline] (0,0) -- (0,2.0) -- (2.0,2.0) -- (2.0,0) -- cycle;
\draw[nbline,line width=2pt] (0,2.0) -- (2.0,2.0);
\foreach \p in {(0.45,1.3),(1.2,0.95),(0.28,0.78),(1.12,0.36),(0.62,0.32),(1.7,1.35),(1.62,0.8),(1.3,1.7),(0.86,1.72)} { \fill[NebulaNavy] \p circle (2.2pt); }
\draw[nbvec] (0.45,1.3) -- (0.729,1.495);
\draw[nbvec] (1.2,0.95) -- (0.881,1.066);
\draw[nbvec] (0.86,1.72) -- (1.03,1.426);
\node[below,font=\footnotesize] at (1.0,-0.3) {Before};

%% --- Flexible piston, AFTER heating (piston has risen)
\begin{scope}[xshift=3.1cm]
\draw[nbline] (0,0) -- (0,2.8) -- (2.0,2.8) -- (2.0,0) -- cycle;
\draw[nbline,line width=2pt] (0,2.8) -- (2.0,2.8);
\foreach \p in {(0.4,0.45),(1.15,0.4),(1.7,0.7),(0.3,1.15),(1.05,1.25),(1.72,1.6),(0.45,2.05),(1.2,2.1),(0.8,2.55)} { \fill[NebulaNavy] \p circle (2.2pt); }
\draw[nbvec] (0.4,0.45) -- (1.051,0.996);
\draw[nbvec] (1.05,1.25) -- (0.314,1.675);
\draw[nbvec] (1.2,2.1) -- (1.625,1.364);
\draw[nbdash] (0,2.0) -- (2.35,2.0);
\draw[nbdash] (2.0,2.8) -- (2.35,2.8);
\draw[nbvec] (2.2,2.02) -- (2.2,2.78);
\node[right,align=left,font=\tiny] at (2.42,2.4) {volume\\increases};
\node[below,font=\footnotesize] at (1.0,-0.3) {After};
\end{scope}

%% --- Rigid sealed vessel, BEFORE heating
\begin{scope}[xshift=7.3cm]
\draw[nbline] (0,0) rectangle (2.0,2.0);
\foreach \p in {(0.45,1.3),(1.2,0.95),(0.28,0.78),(1.12,0.36),(0.62,0.32),(1.7,1.35),(1.62,0.8),(1.3,1.7),(0.86,1.72)} { \fill[NebulaNavy] \p circle (2.2pt); }
\draw[nbvec] (0.45,1.3) -- (0.729,1.495);
\draw[nbvec] (1.2,0.95) -- (0.881,1.066);
\draw[nbvec] (0.86,1.72) -- (1.03,1.426);
\node[below,font=\footnotesize] at (1.0,-0.3) {Before};
\end{scope}

%% --- Rigid sealed vessel, AFTER heating (same volume, faster particles)
\begin{scope}[xshift=10.4cm]
\draw[nbline] (0,0) rectangle (2.0,2.0);
\foreach \p in {(0.42,0.38),(1.1,0.3),(1.68,0.55),(0.3,1),(0.95,0.95),(1.6,1.2),(0.4,1.6),(1.05,1.68),(1.62,1.72)} { \fill[NebulaNavy] \p circle (2.2pt); }
