\draw[nbvec] (0.3,1) -- (1.099,1.291);
\draw[nbvec] (1.6,1.2) -- (0.763,1.348);
\draw[nbvec] (1.05,1.68) -- (1.341,0.881);
\node[below,font=\footnotesize] at (1.0,-0.3) {After};
\end{scope}
